// Normalise the submission and decide whether it is valid.
const b = $json.body || {};
const MEALS = ['Breakfast', 'Lunch', 'Snacks', 'Dinner'];
const roll = String(b.roll_number ?? '').trim().toUpperCase();
const meal = MEALS.find(m => m.toLowerCase() === String(b.meal ?? '').trim().toLowerCase());
const ratingRaw = typeof b.rating === 'number' ? b.rating : (typeof b.rating === 'string' && b.rating.trim() !== '' ? Number(b.rating.trim()) : NaN);
const today = $now.toFormat('yyyy-MM-dd');
const d = String(b.date ?? '').trim();
const date = /^\d{4}-\d{2}-\d{2}$/.test(d) ? d : today;
const comment = String(b.comment ?? '').trim();
let error = '';
if (!roll) error = 'roll_number is required';
else if (!meal) error = 'meal must be one of Breakfast, Lunch, Snacks, Dinner';
else if (!Number.isInteger(ratingRaw) || ratingRaw < 1 || ratingRaw > 5) error = 'rating must be a whole number from 1 to 5';
return [{ json: { valid: error === '', error, roll_number: roll, meal, rating: ratingRaw, comment, date, dedupe_key: roll + '|' + meal + '|' + date, submitted_at: $now.toFormat('yyyy-MM-dd HH:mm:ss') } }];

const key = $('Clean and Validate').first().json.dedupe_key;
const dup = $input.all().some(i => i.json.dedupe_key === key);
return [{ json: { duplicate: dup } }];

const d = String(($json.body || {}).date ?? '').trim();
const date = /^\d{4}-\d{2}-\d{2}$/.test(d) ? d : $now.toFormat('yyyy-MM-dd');
return [{ json: { report_date: date, warden_email: 'warden@example.edu', threshold: 2.5 } }];

// Counts and averages come from the rows, never from the AI.
const cfg = $('Set Report Date').first().json;
const MEALS = ['Breakfast', 'Lunch', 'Snacks', 'Dinner'];
const rows = $input.all().map(i => i.json).filter(r =>
  String(r.date ?? '').trim() === cfg.report_date &&
  MEALS.includes(String(r.meal ?? '').trim()) &&
  String(r.rating ?? '').trim() !== '' && !isNaN(Number(r.rating)));
const round2 = n => Math.round((n + Number.EPSILON) * 100) / 100;
const meals = MEALS.map(name => {
  const mr = rows.filter(r => String(r.meal).trim() === name);
  const avg = mr.length ? round2(mr.reduce((s, r) => s + Number(r.rating), 0) / mr.length) : null;
  return { meal: name, responses: mr.length, average_rating: avg };
});
const total = rows.length;
const overall = total ? round2(rows.reduce((s, r) => s + Number(r.rating), 0) / total) : null;
const comments = rows.filter(r => String(r.comment ?? '').trim() !== '').slice(0, 200)
  .map((r, i) => ({ id: 'C' + (i + 1), meal: String(r.meal).trim(), rating: Number(r.rating), comment: String(r.comment).replace(/\s+/g, ' ').trim() }));
// Attention list uses the unrounded mean, so 2.499 is flagged and 2.5 is not.
const attention = MEALS.filter(name => {
  const mr = rows.filter(r => String(r.meal).trim() === name);
  return mr.length && (mr.reduce((s, r) => s + Number(r.rating), 0) / mr.length) < cfg.threshold;
});
return [{ json: { date: cfg.report_date, total_responses: total, overall_rating: overall, meals, meals_requiring_attention: attention,
  comment_count: comments.length, comments, comments_for_ai: comments.map(c => `${c.id} | ${c.meal} | ${c.rating}/5 | ${c.comment}`).join('\n') } }];

// The AI only decides which comment IDs belong together; counts and quotes come from the real data.
const stats = $('Calculate Ratings').first().json;
const raw = String($input.first().json.text ?? $input.first().json.output ?? '');
let parsed = null;
for (let s = 0; s < raw.length && parsed === null; s++) {
  if (raw[s] !== '{') continue;
  let depth = 0, inStr = false, esc = false;
  for (let e = s; e < raw.length; e++) {
    const ch = raw[e];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') inStr = true; else if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) { try { const c = JSON.parse(raw.slice(s, e + 1)); if (c && Array.isArray(c.complaint_groups) && Array.isArray(c.hygiene_alerts)) parsed = c; } catch (x) {} break; } }
  }
}
const byId = {}; for (const c of stats.comments) byId[c.id] = c;
let top = [], hygiene = [];
if (parsed) {
  top = parsed.complaint_groups.map(g => {
    const ids = [...new Set((Array.isArray(g.comment_ids) ? g.comment_ids : []).map(String))].filter(id => byId[id]);
    return { complaint: String(g.label ?? '').trim(), mentions: ids.length };
  }).filter(g => g.complaint && g.mentions > 0).sort((a, b) => b.mentions - a.mentions).slice(0, 3);
  const seen = new Set();
  for (const a of parsed.hygiene_alerts) {
    const id = String(a.comment_id ?? '');
    if (!byId[id] || seen.has(id)) continue;
    seen.add(id);
    hygiene.push(String(a.issue ?? '').trim() ? `${String(a.issue).trim()} (${byId[id].meal}: "${byId[id].comment}")` : byId[id].comment);
  }
}
return [{ json: { top_complaints: top, hygiene_concerns: hygiene } }];

const s = $('Calculate Ratings').first().json;
const cfg = $('Set Report Date').first().json;
const ai = $('Check AI Answer').isExecuted ? $('Check AI Answer').first().json : { top_complaints: [], hygiene_concerns: [] };
const report = { date: s.date, total_responses: s.total_responses, overall_rating: s.overall_rating, meals: s.meals,
  meals_requiring_attention: s.meals_requiring_attention, top_complaints: ai.top_complaints, hygiene_concerns: ai.hygiene_concerns };
const esc = x => String(x ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const html = `<h2>Mess feedback report: ${esc(report.date)}</h2><p>Responses: ${report.total_responses}, overall ${report.overall_rating ?? 'n/a'} / 5</p><ul>` +
  report.meals.map(m => `<li>${esc(m.meal)}: ${m.responses} responses, average ${m.average_rating ?? 'n/a'}</li>`).join('') + '</ul>' +
  (report.meals_requiring_attention.length ? `<p><b>Needs attention:</b> ${report.meals_requiring_attention.map(esc).join(', ')}</p>` : '') +
  '<h3>Top complaints</h3><ul>' + report.top_complaints.map(c => `<li>${esc(c.complaint)} (${c.mentions})</li>`).join('') + '</ul>' +
  '<h3>Hygiene concerns</h3><ul>' + report.hygiene_concerns.map(h => `<li>${esc(h)}</li>`).join('') + '</ul>';
return [{ json: { report, subject: 'Mess feedback report ' + report.date, html, to: cfg.warden_email } }];
